import * as THREE from 'three';
export function makeEffects(scene){return{scene,particles:[],slashes:[]};}
export function burst(effects,position,color='#f2d37b'){const material=new THREE.MeshBasicMaterial({color});for(let i=0;i<10;i++){const mesh=new THREE.Mesh(new THREE.SphereGeometry(.07+Math.random()*.06,5,5),material.clone());mesh.position.copy(position);mesh.position.y+=.8;effects.scene.add(mesh);const a=Math.random()*Math.PI*2,s=1.5+Math.random()*3;effects.particles.push({mesh,v:new THREE.Vector3(Math.cos(a)*s,1+Math.random()*2,Math.sin(a)*s),life:.55});}}
export function slash(effects,position,facing){const g=new THREE.Group();const material=new THREE.MeshBasicMaterial({color:'#a7fff0',transparent:true,opacity:.9});const arc=new THREE.Mesh(new THREE.TorusGeometry(1.35,.07,6,28,Math.PI*1.2),material);arc.rotation.x=Math.PI/2;g.add(arc);g.position.set(position.x+facing.x*1.4,.95,position.z+facing.z*1.4);g.rotation.y=Math.atan2(facing.x,facing.z);effects.scene.add(g);effects.slashes.push({mesh:g,life:.22});burst(effects,g.position,'#9affef');}
export function updateEffects(effects,dt){for(const p of effects.particles){p.life-=dt;p.mesh.position.addScaledVector(p.v,dt);p.v.y-=5*dt;p.mesh.scale.multiplyScalar(.985);}for(const p of effects.particles.filter(x=>x.life<=0)){effects.scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();}effects.particles=effects.particles.filter(x=>x.life>0);for(const s of effects.slashes){s.life-=dt;s.mesh.scale.multiplyScalar(1+dt*2);s.mesh.material.opacity=Math.max(0,s.life/.22);}for(const s of effects.slashes.filter(x=>x.life<=0)){effects.scene.remove(s.mesh);s.mesh.traverse(o=>{if(o.material)o.material.dispose();if(o.geometry)o.geometry.dispose();});}effects.slashes=effects.slashes.filter(x=>x.life>0);}
